        if len(source) == 7:
            cycle = [source[5], source[6], source[0], source[1], source[3], source[4], source[2]]
            return [[cycle[r % len(cycle)]] * w for r in range(h)]
        return [[source[r % len(source)]] * w for r in range(h)]

    # Otherwise, each diagonal track fixes one residue class of c-r.
    # The number of parallel tracks is the diagonal tiling's period.
    tracks = {}
    for r, row in enumerate(grid):
        for c, color in enumerate(row):
