 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])

    bars = [row[0] for row in grid if row[0] and all(v == row[0] for v in row)]
    if bars:
        # The solid stripes are a seed sequence, reordered into the output cycle.
        if len(bars) == 7:
            cycle = [bars[5], bars[6], bars[0], bars[1], bars[3], bars[4], bars[2]]
        else:
            cycle = bars
        return [[cycle[r % len(cycle)]] * w for r in range(h)]

    # The diagonal tracks are a compact encoding of a repeating diagonal
    # pattern. Extend all diagonal lines and retain their original colors.
    out = [[0] * w for _ in range(h)]
    for r, row in enumerate(grid):
        for c, color in enumerate(row):
            if not color:
                continue
            # A unit-slope track has invariant c-r; fill its parallel diagonal.
            offset = c - r
            for rr in range(h):
                cc = rr + offset
                if 0 <= cc < w:
                    out[rr][cc] = color
    return out

