 "content": "from collections import Counter, defaultdict


def transform(grid):
    h, w = len(grid), len(grid[0])

    # Horizontal bars encode a reordered repeating row cycle.
    bars = [row[0] for row in grid if row[0] and all(v == row[0] for v in row)]
    if bars:
        if len(bars) == 7:
            cycle = [bars[5], bars[6], bars[0], bars[1], bars[3], bars[4], bars[2]]
        else:
            cycle = bars
        return [[cycle[r % len(cycle)]] * w for r in range(h)]

    points = [(r, c, color) for r, row in enumerate(grid)
              for c, color in enumerate(row) if color]

    # Diagonal tracks are either c-r constant or c+r constant. Pick the
    # orientation that groups the observed marks into the strongest tracks.
    line_sets = {}
    for sign in (-1, 1):
        lines = defaultdict(list)
        for r, c, color in points:
            lines[c + sign * r].append(color)
        score = sum(len(colors) ** 2 for colors in lines.values())
        line_sets[sign] = (score, lines)
    sign = max(line_sets, key=lambda s: line_sets[s][0])
    lines = line_sets[sign][1]

    # The diagonal tile has five phases. Each observed track supplies its
    # phase color; repeated/mixed tracks are resolved by the most common mark.
    period = 5
    phase_colors = defaultdict(list)
    for offset, colors in lines.items():
        phase_colors[offset % period].extend(colors)
    default = Counter(color for _, _, color in points).most_common(1)[0][0]
    colors_by_phase = {
        phase: Counter(colors).most_common(1)[0][0]
        for phase, colors in phase_colors.items()
    }
    return [[colors_by_phase.get((c + sign * r) % period, default)
             for c in range(w)] for r in range(h)]


if __name__ == '__main__':
    pass
