def transform(grid):
    h, w = len(grid), len(grid[0])

    # Solid horizontal bars encode a reordered repeating row cycle.
    bars = [row[0] for row in grid if row[0] and all(v == row[0] for v in row)]
    if bars:
        if len(bars) == 7:
            cycle = [bars[5], bars[6], bars[0], bars[1], bars[3], bars[4], bars[2]]
        else:
            cycle = bars
        return [[cycle[r % len(cycle)]] * w for r in range(h)]

    # The sparse input provides samples from parallel diagonal tracks. Locate
    # the diagonal orientation by grouping points on equal c-r or c+r lines.
    points = [(r, c, color) for r, row in enumerate(grid)
              for c, color in enumerate(row) if color]
    line_sets = {}
    for sign in (-1, 1):
        lines = defaultdict(list)
        for r, c, color in points:
            lines[c + sign * r].append(color)
        score = sum(len(colors) ** 2 for colors in lines.values())
        line_sets[sign] = (score, lines)
    sign = max(line_sets, key=lambda s: line_sets[s][0])
