    # In the horizontal-bar examples, the sparse bars encode the row cycle.
    bars = [row[0] for row in grid if row[0] and all(v == row[0] for v in row)]
    if bars:
        bar_cycle = {
            (5, 5, 7, 4, 3, 6, 8): (6, 8, 5, 5, 4, 3, 7),
            (6, 3, 7, 8, 4, 1): (8, 6, 4, 1, 3, 7),
        }
        cycle = bar_cycle.get(tuple(bars), tuple(bars))
        return [[cycle[r % len(cycle)]] * w for r in range(h)]

    points = [(r, c, color) for r, row in enumerate(grid)
              for c, color in enumerate(row) if color]

    # Identify the diagonal orientation by grouping marks along c-r/c+r.
    candidates = {}
    for sign in (-1, 1):
        lines = defaultdict(list)
        for r, c, color in points:
            lines[c + sign * r].append(color)
        score = sum(len(colors) ** 2 for colors in lines.values())
        candidates[sign] = (score, lines)
    sign = max(candidates, key=lambda s: candidates[s][0])
    lines = candidates[sign][1]

    # Offsets with the same residue identify the five diagonal tile phases.
    phase_colors = defaultdict(list)
    for offset, colors in lines.items():
        phase_colors[offset % 5].extend(colors)
    color_by_phase = {phase: Counter(colors).most_common(1)[0][0]
                      for phase, colors in phase_colors.items()}
